            ],
            constraints: [
                // Bin 0 holds at most 2: count items in bin 0 <= 2
                // Equivalent: (1-a) + (1-b) + (1-c) <= 2 → -a - b - c + 3 <= 2 → -a - b - c <= -1 → a + b + c >= 1
                // At least 1 item in bin 1
                variant('linear', {
                    expr: { terms: [{ var: "a", coeff: 1n }, { var: "b", coeff: 1n }, { var: "c", coeff: 1n }], constant: 0n },
