                            $(droppedRowBind.write(mv.to.row.parse(IntegerType)));
                            $(pendingRowBind.write(mv.to.row.parse(IntegerType)));
                            $(droppedDayBind.write(slotDay(mv.to.slot)));
                            $(droppedBucketBind.write(slotBucket(mv.to.slot)));
